using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;

namespace Jamera.Complaints
{
    public partial class Complaints : DevExpress.XtraEditors.XtraUserControl
    {
        Complaints_Controller complaints_controller = new Complaints_Controller();
        public Complaints()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            //sqlDataSource1.Fill();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            UC_Opener_Form form = new UC_Opener_Form("New Complaint", new New_Complaint());
            form.Show();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Complaint complaint = complaints_controller.Get_Complaint(Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Code"])));
                UC_Opener_Form form = new UC_Opener_Form("Edit Complaint", new Edit_Complaint(complaint));
                form.Show();
            }
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }
    }
}
